{
  "mechanisms": [
    {
      "name": "mb_mf_mixture",
      "title": "MB/MF Mixture Weight",
      "description": "Weights the model-based and model-free Q-values to determine the net Stage 1 Q-values.",
      "params": [
        {
          "name": "w",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_net = w * q_stage1_mb + (1 - w) * q_stage1_mf",
      "expressible_in_slots": true
    },
    {
      "name": "eligibility_trace",
      "title": "Eligibility Trace",
      "description": "Updates the Stage 1 model-free Q-value for the chosen action based on the Stage 2 reward prediction error.",
      "params": [
        {
          "name": "lam",
          "bounds": [0, 1]
        }
      ],
      "evidence": "q_stage1_mf[action_1[trial]] += learning_rate * lam * delta_stage2",
      "expressible_in_slots": true
    },
    {
      "name": "stage_1_perseveration",
      "title": "Stage 1 Choice Perseveration",
      "description": "Adds a bonus to the Stage 1 logits for repeating the action chosen in Stage 1 of the previous trial.",
      "params": [
        {
          "name": "pers_st1",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "pers_bonus_1 = np.zeros(2)\nif trial > 0:\n    pers_bonus_1[action_1[trial-1]] = pers_st1\nexp_q1_net = np.exp(beta * q_stage1_net + pers_bonus_1)",
      "expressible_in_slots": true
    },
    {
      "name": "stage_2_perseveration",
      "title": "Stage 2 Choice Perseveration",
      "description": "Adds a bonus to the Stage 2 logits for repeating the action previously chosen in the current Stage 2 state.",
      "params": [
        {
          "name": "pers_st2",
          "bounds": [-5, 5]
        }
      ],
      "evidence": "pers_bonus_2 = np.zeros(2)\nif last_action2[state_idx] != -1:\n    pers_bonus_2[last_action2[state_idx]] = pers_st2\nexp_q2 = np.exp(beta * q_stage2_mf[state_idx] + pers_bonus_2)",
      "expressible_in_slots": true
    },
    {
      "name": "unchosen_value_decay",
      "title": "Unchosen Value Decay",
      "description": "Decays the Q-values of all unchosen actions in both stages towards 0.5.",
      "params": [
        {
          "name": "decay",
          "bounds": [0, 1]
        }
      ],
      "evidence": "unchosen_a1 = 1 - action_1[trial]\nq_stage1_mf[unchosen_a1] += decay * (0.5 - q_stage1_mf[unchosen_a1])\nfor s in range(2):\n    for a in range(2):\n        if not (s == state_idx and a == action_2[trial]):\n            q_stage2_mf[s, a] += decay * (0.5 - q_stage2_mf[s, a])",
      "expressible_in_slots": true
    },
    {
      "name": "q_init_05",
      "title": "Q-value Initialization to 0.5",
      "description": "Initializes all model-free Q-values to 0.5 instead of 0.",
      "params": [],
      "evidence": "q_stage1_mf = np.zeros(2) + 0.5\nq_stage2_mf = np.zeros((2, 2)) + 0.5",
      "expressible_in_slots": true
    }
  ]
}
